index 0000000..9dfc5a3
--- /dev/null
+++ b/apps/game/src/passengers.ts
@@ -0,0 +1,63 @@
+export type PassengerShape = "circle" | "triangle" | "square";
+
+export type PassengerStation = { id: string; shape: PassengerShape };
+
+export type Passenger = { id: number; destination: PassengerShape };
+
+export type PassengerState = {
+  queues: Record<string, Passenger[]>;
+  /** ms of running time until the next passenger appears. */
+  untilNext: number;
+  /** Generated passengers so far; also drives the fixed sequence. */
+  generated: number;
+};
+
+export const MAX_WAITING = 12;
+export const SPAWN_EVERY_MS = 1500;
+const SEED = 20261030;
+const SHAPES: PassengerShape[] = ["circle", "triangle", "square"];
+
+/** Deterministic value in [0, 1) for the n-th generated passenger (mulberry32 on seed + n). */
+function sequenceValue(n: number, salt: number): number {
+  let t = (SEED + n * 2 + salt + 0x6d2b79f5) >>> 0;
+  t = Math.imul(t ^ (t >>> 15), t | 1);
+  t ^= t + Math.imul(t ^ (t >>> 7), t | 61);
+  return ((t ^ (t >>> 14)) >>> 0) / 4294967296;
+}
+
+export function createPassengerState(): PassengerState {
+  return { queues: {}, untilNext: SPAWN_EVERY_MS, generated: 0 };
+}
+
+/** Picks origin and destination for the next passenger, or null when every station is full. */
+export function nextPassenger(
+  state: PassengerState,
+  stations: PassengerStation[],
+): { stationId: string; destination: PassengerShape } | null {
+  const open = stations.filter((s) => (state.queues[s.id]?.length ?? 0) < MAX_WAITING);
+  if (open.length === 0) return null;
+  const origin = open[Math.floor(sequenceValue(state.generated, 0) * open.length)];
+  const choices = SHAPES.filter((shape) => shape !== origin.shape);
+  const destination = choices[Math.floor(sequenceValue(state.generated, 1) * choices.length)];
+  return { stationId: origin.id, destination };
+}
+
+/** Advances generation by `ms` of running time. Paused time is never passed in, so nothing accumulates. */
+export function advancePassengers(
+  state: PassengerState,
+  ms: number,
+  stations: PassengerStation[],
+): PassengerState {
+  let { untilNext, generated } = state;
+  let queues = state.queues;
+  untilNext -= ms;
+  while (untilNext <= 0) {
+    untilNext += SPAWN_EVERY_MS;
+    const next = nextPassenger({ queues, untilNext, generated }, stations);
+    if (!next) continue;
+    const queue = queues[next.stationId] ?? [];
+    queues = { ...queues, [next.stationId]: [...queue, { id: generated, destination: next.destination }] };
+    generated += 1;
+  }
+  return { queues, untilNext, generated };
+}
